package com.musiccatalog.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="albums",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","apple_catalog_id"})) public class Album { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="apple_catalog_id",nullable=false) private Long appleCatalogId; @Column(nullable=false) private String title; @Column(nullable=false) private String artistName; private String genre; private LocalDate releaseDate; private Integer trackCount; @Column(length=1000) private String artworkUrl; private Integer userRating; @Column(length=2000) private String userNotes; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @PrePersist void create(){createdAt=updatedAt=Instant.now();} @PreUpdate void update(){updatedAt=Instant.now();}
 public Long getId(){return id;} public Long getAppleCatalogId(){return appleCatalogId;} public void setAppleCatalogId(Long v){appleCatalogId=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getArtistName(){return artistName;} public void setArtistName(String v){artistName=v;} public String getGenre(){return genre;} public void setGenre(String v){genre=v;} public LocalDate getReleaseDate(){return releaseDate;} public void setReleaseDate(LocalDate v){releaseDate=v;} public Integer getTrackCount(){return trackCount;} public void setTrackCount(Integer v){trackCount=v;} public String getArtworkUrl(){return artworkUrl;} public void setArtworkUrl(String v){artworkUrl=v;} public Integer getUserRating(){return userRating;} public void setUserRating(Integer v){userRating=v;} public String getUserNotes(){return userNotes;} public void setUserNotes(String v){userNotes=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} }
